fn all_characters_same(char_arr: &Vec<char>) -> bool {
    // If there are 0 or 1 characters, the condition holds vacuously.
    if char_arr.len() <= 1 {
        return true;
    }
    // Otherwise, compare every character against the first one.
    let first = char_arr[0];
    char_arr.iter().skip(1).all(|&c| c == first)
}

